using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Application.Bloco8; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Api.Controllers;
[ApiController,Authorize,Route("api/protocolo-externo")] public sealed class ProtocoloExternoController:ControllerBase { private readonly IProtocoloDigitalService _s; public ProtocoloExternoController(IProtocoloDigitalService s)=>_s=s; [HttpGet] public async Task<ActionResult<ApiResponse<PagedResult<Bloco8RegistroDto>>>> Listar([FromQuery]int pagina=1,CancellationToken ct=default)=>From(await _s.ListarAsync("protocolo_externo",pagina,20,ct)); [HttpPost] public async Task<ActionResult<ApiResponse<long>>> Criar(Bloco8RegistroRequest r,CancellationToken ct)=>From(await _s.CriarAsync("protocolo_externo",r,HttpContext.TraceIdentifier,ct)); [HttpGet("{id:long}")] public async Task<ActionResult<ApiResponse<Bloco8RegistroDto>>> Obter(long id,CancellationToken ct)=>From(await _s.ObterAsync("protocolo_externo",id,ct)); private ActionResult<ApiResponse<T>> From<T>(Result<T> r)=>r.IsSuccess?Ok(ApiResponse<T>.Ok(r.Value!,correlationId:HttpContext.TraceIdentifier)):BadRequest(ApiResponse<T>.Fail(r.Error??"Falha.",HttpContext.TraceIdentifier)); }
